import heapq

def func(arr,k):
    # Create a dictionary to count occurrences of each number
    num_count = {}
    for sublist in arr:
        for num in sublist:
            if num in num_count:
                num_count[num] += 1
            else:
                num_count[num] = 1

    # Use a min-heap to keep track of the top k numbers
    max_heap = []
    for num, count in num_count.items():
        if len(max_heap) < k:
            heapq.heappush(max_heap, (-count, num))
        elif -count > max_heap[0][0]:
            heapq.heappop(max_heap)
            heapq.heappush(max_heap, (-count, num))

    # Extract the numbers from the heap
    result = [-num for _, num in max_heap]
    return result[::-1]  # Reverse the list to get the correct order
