def max_len_sub(arr, n):
    # Initialize dp array where dp[i] represents the length of the longest subsequence ending at arr[i]
    dp = [1] * n

    # Iterate through each element in the array starting from the second element
    for i in range(1, n):
        # For each element, check all previous elements to see if they can form a valid subsequence
        for j in range(i):
            # If the absolute difference between current and previous element is less than or equal to n-1,
            # update dp[i] to be the maximum of its current value and dp[j] + 1
            if abs(arr[i] - arr[j]) <= n - 1:
                dp[i] = max(dp[i], dp[j] + 1)

    # The maximum value in dp array will be the length of the longest subsequence
    return max(dp)
```

