def count_no_of_ways(n, k):
    if n == 0:
        return 0
    elif n == 1:
        return k
    else:
        # dp[i][j] represents the number of ways to paint i posts using j colors
        dp = [[0] * k for _ in range(n)]

        # Base cases
        for i in range(k):
            dp[0][i] = 1

        for i in range(1, n):
            for j in range(k):
                # If the current post has the same color as the previous post
                if j == 0:
                    dp[i][j] += sum(dp[i-1][k] for k in range(j+1))
                # If the current post has a different color from the previous post
                else:
                    dp[i][j] += sum(dp[i-1][k] for k in range(j))

        # The total number of ways is the sum of all ways to paint the last post
        return sum(dp[-1])
