def permutation_coefficient(n, k):
    # Calculate factorial using recursion
    def factorial(x):
        if x == 0 or x == 1:
            return 1
        else:
            return x * factorial(x-1)

    # Calculate permutation coefficient using formula n! / (n-k)!
    return factorial(n) // factorial(n-k)
